import express, {
  type Application,
  type Request,
  type Response,
  type NextFunction,
} from "express";
import cors from "cors";
import helmet from "helmet";
import authRoutes from "../modules/auth/auth.routes.js"; 
import ApiError from "../errors/ApiError.js";
import notFound from "../middleware/notFound.js";
import globalErrorHandler from "../middleware/globalErrorHandler.js";
import parcelRoutes from "../modules/parcel/parcel.routes.js";
import paymentRoutes from "../modules/payment/payment.routes.js";
import adminRoutes from "../modules/admin/admin.routes.js";
import config from "../config/index.js";
import sendResponse from "../utils/sendResponse.js";
import paymentWebhookRoutes from "../modules/payment/payment.webhook.routes.js";

const app: Application = express();

app.use(helmet());

app.use(
  cors({
    origin: config.appUrl,
    credentials: true,
  }),
);

app.use(
  "/api/v1/payments/webhook",
  express.raw({ type: "application/json" }),
  paymentWebhookRoutes,
);

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.get("/health", (req: Request, res: Response) => {
  return sendResponse(res, {
    statusCode: 200,
    success: true,
    message: "API is healthy",
    data: { status: "running" },
  });
});

app.get("/", (req: Request, res: Response) => {
  return res.send("Courier & Logistics Platform API is running!");
});

app.get("/test-error", (req: Request, res: Response, next: NextFunction) => {
  return next(new ApiError(400, "This is a test error"));
});

app.use("/api/v1/auth", authRoutes);
app.use("/api/v1/parcels", parcelRoutes);
app.use("/api/v1/payments", paymentRoutes);
app.use("/api/v1/admin", adminRoutes);

app.use(notFound);
app.use(globalErrorHandler);

export default app;